<template><div class="page"><div class="page-header"><h2>免费更换</h2></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="renew_id" label="更换单号" width="120"/><el-table-column prop="store_id" label="门店" width="80"/><el-table-column prop="short_description" label="简述" min-width="130" show-overflow-tooltip/><el-table-column prop="old_device_id" label="旧设备" width="140"/><el-table-column prop="new_device_id" label="新设备" width="140"/><el-table-column label="状态" width="80"><template #default="{row}"><el-tag :type="statusTag(row.current_status)" size="small">{{ statusLabel(row.current_status) }}</el-tag></template></el-table-column><el-table-column prop="count" label="数量" width="60"/><el-table-column prop="create_time" label="日期" width="100"/><el-table-column prop="creator" label="创建人" width="80"/></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-drawer v-model="drawer" title="免费更换详情" size="550px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="单号">{{ detail.renew_id }}</el-descriptions-item><el-descriptions-item label="门店">{{ detail.store_id }}</el-descriptions-item><el-descriptions-item label="简述">{{ detail.short_description }}</el-descriptions-item><el-descriptions-item label="状态"><el-tag :type="statusTag(detail.current_status)" size="small">{{ statusLabel(detail.current_status) }}</el-tag></el-descriptions-item><el-descriptions-item label="旧设备">{{ detail.old_device_id }}</el-descriptions-item><el-descriptions-item label="新设备">{{ detail.new_device_id }}</el-descriptions-item><el-descriptions-item label="数量">{{ detail.count }}</el-descriptions-item><el-descriptions-item label="是否返回">{{ detail.is_back==='Y'?'是':'否' }}</el-descriptions-item><el-descriptions-item label="详细描述" :span="2">{{ detail.detail_description || '-' }}</el-descriptions-item></el-descriptions><h4 style="margin:16px 0 8px">更换设备明细</h4><el-table :data="detail.equipments||[]" size="small" stripe><el-table-column prop="device_id" label="旧机ID" width="140"/><el-table-column prop="new_device_id" label="新机ID" width="140"/><el-table-column prop="delivery_id" label="送货单号" width="100"/><el-table-column label="完成"><template #default="{r}"><el-tag :type="r.is_finish==='1'?'success':'info'" size="small">{{ r.is_finish==='1'?'已完成':'未完成' }}</el-tag></template></el-table-column></el-table></template></el-drawer></div></template>
<script setup lang="ts">import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {fetchFreeReplace,type FreeReplaceRecord} from '@/api/itsm'
const{items,loading,page,perPage,total}=useListPage<FreeReplaceRecord>(fetchFreeReplace);const{drawer,detail,open}=useDetailDrawer<FreeReplaceRecord>()
function statusTag(s:string){const m:Record<string,string>={'1':'info','2':'primary','3':'success','4':'warning','5':'primary','9':'danger'};return m[s]||'info'}
function statusLabel(s:string){const m:Record<string,string>={'1':'新建','2':'分配','3':'关闭','4':'未解决','5':'已解决','9':'作废'};return m[s]||s}</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}</style>
